/**
 * Node: Dashboard Backend (Data Fetcher) - Multi-Alliance Production
 * Version: 14.2.0 (ISK Logic & OR Filter Fix)
 */

const Redis = require('ioredis');

const inputData = $input ? $input.first().json : items[0].json;
const params = inputData.query || {};

const REDIS_CONFIG = { 
    host: 'redis', 
    port: 6379, 
    db: 0, 
    connectTimeout: 5000, 
    maxRetriesPerRequest: 2 
};
const FETCH_LIMIT = parseInt(params.limit) || 50; 
const DEEP_SEARCH_LIMIT = 200; 
const STATS_WINDOW_DAYS = 30;

const KEY_KILLS_ALL = 'intel:kills:all';
const KEY_KILLS_NPC = 'intel:kills:npc';
const KEY_KILL_DATA = 'intel:kill:data';
const KEY_CACHED_STATS = 'intel:cached:stats';
const KEY_CACHED_TRENDS = 'intel:cached:trends';

const latestKnownId = params.latest_known_id ? String(params.latest_known_id) : null;
const beforeKillId = params.before_kill_id ? String(params.before_kill_id) : null;
const allianceIdParam = params.alliance_id ? String(params.alliance_id) : null;
const allianceIdsArr = allianceIdParam ? allianceIdParam.split(',').map(s => s.trim()).filter(Boolean) : [];
const allianceIds = new Set(allianceIdsArr);

const filtersMain = new Set(params.filters_main ? params.filters_main.split(',') : []);
const filtersSpace = new Set(params.filters_space ? params.filters_space.split(',') : []);
const filtersIsk = new Set(params.filters_isk ? params.filters_isk.split(',') : []);
const filtersShipTarget = params.filters_ship_target || 'victim';
const filtersShip = new Set(params.filters_ship ? params.filters_ship.split(',') : []);
const searchQuery = (params.search_query || '').toLowerCase().trim();

const redis = new Redis(REDIS_CONFIG);

let finalKills = [];
let total_count = 0;
let stats_24h = { kills: 0, isk: 0 };
let trends = {};
let isk_distribution = {}; 
let activity_heatmap = {};
let oldest_kill_id_for_client = null;
let allianceStatsDict = {}; 
let allianceSummary = null; 
let latest_db_killmail_time = null;

let vsHeadToHead = null;
let interactionMatrix = null;

const DETAILED_CLASSES_SET = new Set(['interceptor','assault_frigate','covert_ops','stealth_bomber','electronic_attack','logistics_frigate','mining_frigate','expedition_frigate','rookie_ship','interdictor','command_destroyer','tactical_destroyer','logistics_destroyer','heavy_assault','logistics','force_recon','combat_recon','command_ship','strategic_cruiser','flag_cruiser','attack_battlecruiser','battlecruiser','marauder','black_ops','battleship','lancer_dreadnought','force_auxiliary','supercarrier','titan','capital_industrial','blockade_runner','deep_space_transport','mining_barge','exhumer','jump_freighter','industrial_command','hauler','freighter','industrial_base','light_fighter','heavy_fighter','control_tower','starbase_structure','sentry_gun','orbital_infrastructure','mobile_cyno','mobile_warp_disruptor','mobile_tractor_unit','mobile_observatory']);

/**
 * Filter individual killmails based on user criteria.
 * Fix: ISK filtering now uses .some() to correctly handle multiple range selections.
 */
function filterKill(kill) {
    if (allianceIds.size > 0) {
        const vId = String(kill.victim?.alliance_id || '0');
        const aIds = new Set(kill.attackers.map(a => String(a.alliance_id || '0')));
        if (!allianceIds.has(vId) && ![...aIds].some(id => allianceIds.has(id))) return false;
    }

    if (filtersMain.size > 0) {
        if (filtersMain.has('solo') && !kill.is_solo) return false;
        if (filtersMain.has('fleet') && kill.is_solo) return false;
        if (filtersMain.has('npc')) {
            const fb = kill.attackers.find(a => a.final_blow);
            if (!fb || !fb.is_npc) return false;
        }
        if (filtersMain.has('hide-pods') && kill.victim_ship_class === 'capsule') return false;
        if (filtersMain.has('hide-structures')) {
            const b = (kill.victim_ship_class || '').toLowerCase();
            const d = (kill.victim_ship_class_detailed || '').toLowerCase();
            const s = ['structure', 'pos', 'control_tower', 'starbase_structure', 'sentry_gun', 'deployable', 'mobile_cyno', 'customs_office', 'fighter', 'light_fighter', 'heavy_fighter', 'orbital_infrastructure', 'mobile_warp_disruptor', 'mobile_tractor_unit', 'mobile_observatory'];
            if (s.includes(b) || s.includes(d)) return false;
        }
        if (filtersMain.has('hide-trash') && ['rookie_ship', 'shuttle'].includes(kill.victim_ship_class)) return false;
    }

    if (filtersSpace.size > 0) {
        const st = (kill.space_type || 'unknown').toLowerCase();
        const map = {'hs':'highsec','ls':'lowsec','ns':'nullsec','wh':'wormhole','ab':'abyssal'};
        if (![...filtersSpace].some(f => map[f] === st)) return false;
    }

    // ISK FILTER LOGIC (OR match between selected ranges)
    if (filtersIsk.size > 0) {
        const v = parseFloat(kill.total_value) || 0;
        const matchesIsk = Array.from(filtersIsk).some(f => {
            if (f === 'sub10m')   return v < 1e7;
            if (f === '10m-100m') return v >= 1e7 && v < 1e8;
            if (f === '100m-1b')  return v >= 1e8 && v < 1e9;
            if (f === '1b-10b')   return v >= 1e9 && v < 1e10;
            if (f === '10b-20b')  return v >= 1e10 && v < 2e10;
            if (f === '20b-50b')  return v >= 2e10 && v < 5e10;
            if (f === '50b')      return v >= 5e10;
            return false;
        });
        if (!matchesIsk) return false;
    }

    if (filtersShip.size > 0) {
        const matchVictim = filtersShip.has(kill.victim_ship_class) || filtersShip.has(kill.victim_ship_class_detailed) || filtersShip.has(String(kill.victim?.ship_type_id));
        const matchAttacker = kill.attackers && kill.attackers.some(a => filtersShip.has(a.ship_class) || filtersShip.has(a.ship_class_detailed) || filtersShip.has(String(a.ship_type_id)));

        if (filtersShipTarget === 'victim' && !matchVictim) return false;
        if (filtersShipTarget === 'attacker' && !matchAttacker) return false;
        if (filtersShipTarget === 'either' && !matchVictim && !matchAttacker) return false;
    }

    if (searchQuery.length > 0) {
        const terms = searchQuery.toLowerCase().split(' ').filter(t => t.length > 0);
        const text = [kill.killmail_id, kill.solar_system_name, kill.victim?.character_name, kill.victim?.corporation_name, kill.victim?.alliance_name, kill.victim?.ship_type_name, kill.victim_ship_class, kill.victim_ship_class_detailed].join(' ').toLowerCase();
        if (!terms.every(t => text.includes(t))) return false;
    }
    return true;
}

return (async () => {
    try {
        let sourceKeys = [];
        if (allianceIds.size > 0) {
            allianceIds.forEach(id => sourceKeys.push(`intel:followed:alliance:${id}`));
        } else if (filtersShip.size > 0) {
            for (const s of filtersShip) {
                const isDetailed = DETAILED_CLASSES_SET.has(s);
                if (filtersShipTarget === 'victim' || filtersShipTarget === 'either') {
                    sourceKeys.push(isDetailed ? `intel:losses:ship_class_detailed:${s}` : `intel:losses:ship_class:${s}`);
                }
                if (filtersShipTarget === 'attacker' || filtersShipTarget === 'either') {
                    sourceKeys.push(isDetailed ? `intel:kills:ship_class_detailed:${s}` : `intel:kills:ship_class:${s}`);
                }
            }
        } else if (filtersMain.has('npc')) {
            sourceKeys = [KEY_KILLS_NPC];
        } else if (filtersIsk.size > 0) {
            // Map valid keys to Redis set paths
            filtersIsk.forEach(f => {
                if (['sub10m','10m-100m','100m-1b','1b-10b','10b-20b','20b-50b','50b'].includes(f)) {
                    sourceKeys.push(`intel:kills:isk:${f}`);
                }
            });
        } else {
            sourceKeys = [KEY_KILLS_ALL];
        }

        if (latestKnownId) {
            const results = [];
            for (const k of sourceKeys) {
                const s = await redis.zscore(k, latestKnownId);
                if (s) {
                    const ids = await redis.zrangebyscore(k, `(${s}`, '+inf', 'WITHSCORES');
                    for (let i = 0; i < ids.length; i += 2) results.push({ id: ids[i], ts: parseFloat(ids[i + 1]) });
                }
            }
            const unique = Array.from(new Map(results.map(i => [i.id, i])).values()).sort((a,b) => b.ts - a.ts);
            if (unique.length > 0) {
                const pipe = redis.pipeline();
                unique.forEach(i => pipe.hget(KEY_KILL_DATA, i.id));
                const data = await pipe.exec();
                finalKills = data.filter(([e]) => !e).map(([,j]) => JSON.parse(j)).filter(filterKill);
            }
        } else {
            let iter = 0, cursor = beforeKillId;
            while (iter < DEEP_SEARCH_LIMIT && finalKills.length < FETCH_LIMIT) {
                let batch = [];
                let bSize = FETCH_LIMIT >= 500 ? 10000 : (iter >= 10 ? 10000 : 500);
                for (const k of sourceKeys) {
                    let ids = cursor 
                        ? await redis.zrevrangebyscore(k, `(${await redis.zscore(k, cursor)}`, '-inf', 'WITHSCORES', 'LIMIT', 0, bSize) 
                        : await redis.zrevrange(k, 0, bSize, 'WITHSCORES');
                    for (let i = 0; i < ids.length; i += 2) batch.push({ id: ids[i], ts: parseFloat(ids[i + 1]) });
                }
                if (batch.length === 0) break;
                const sorted = Array.from(new Map(batch.map(i => [i.id, i])).values()).sort((a,b) => b.ts - a.ts);
                cursor = sorted[sorted.length - 1].id;
                const pipe = redis.pipeline();
                sorted.forEach(i => pipe.hget(KEY_KILL_DATA, i.id));
                const data = await pipe.exec();
                finalKills.push(...data.filter(([e])=>!e).map(([,j])=>JSON.parse(j)).filter(filterKill));
                iter++;
            }
            finalKills = finalKills.slice(0, FETCH_LIMIT);
        }

        if (finalKills.length > 0) oldest_kill_id_for_client = finalKills[finalKills.length - 1].killmail_id;

        // Fetch Stats
        const [csRes, ctRes] = await redis.pipeline().get(KEY_CACHED_STATS).get(KEY_CACHED_TRENDS).exec();
        if (csRes[1]) {
            const cs = JSON.parse(csRes[1]);
            stats_24h = cs.stats_24h; total_count = cs.total_count; latest_db_killmail_time = cs.latest_db_killmail_time;
        }
        trends = ctRes[1] ? JSON.parse(ctRes[1]) : trends;

        const pipe = redis.pipeline();
        const win = Math.floor(Date.now()/1000) - (STATS_WINDOW_DAYS * 86400);
        pipe.zcount(KEY_KILLS_ALL, win, '+inf');
        ['sub10m','10m-100m','100m-1b','1b-10b','10b-20b','20b-50b','50b'].forEach(f => pipe.zcount(`intel:kills:isk:${f}`, win, '+inf'));
        for(let h=0; h<24; h++) pipe.zcount(`intel:kills:hour:${h}`, win, '+inf');

        const idsList = Array.from(allianceIds);
        idsList.forEach(id => pipe.hgetall(`alliance:summary:${id}`));

        const res = await pipe.exec();
        const t30 = res[0][1] || 1;
        ['sub10m','10m-100m','100m-1b','1b-10b','10b-20b','20b-50b','50b'].forEach((k,i) => {
            isk_distribution[k] = { count: res[i+1][1], percent: parseFloat(((res[i+1][1]/t30)*100).toFixed(1)) };
        });
        for(let h=0; h<24; h++) activity_heatmap[h] = { count: res[h+8][1], percent: parseFloat(((res[h+8][1]/t30)*100).toFixed(1)) };

        if (idsList.length > 0) {
            const extraIds = new Set();
            res.slice(32).forEach((r, i) => {
                const s = r[1];
                if (s && Object.keys(s).length > 0) {
                    const id = idsList[i];
                    allianceStatsDict[id] = { kills: Number(s.kills), losses: Number(s.losses), isk_destroyed: Number(s.iskDestroyed), isk_lost: Number(s.iskLost), efficiency: Number(s.efficiency), ratio: Number(s.ratio), activePilots: Number(s.activePilots), lastSeen: Number(s.lastSeen), topShip: s.topShip, topShipId: s.topShipId || null, maxKillId: s.maxKillId, maxLossId: s.maxLossId, kills_final: Number(s.killsFinal), kills_assist: Number(s.killsAssist) };
                    if (s.maxKillId) extraIds.add(s.maxKillId); if (s.maxLossId) extraIds.add(s.maxLossId);
                }
            });
            if (extraIds.size > 0) {
                const kPipe = redis.pipeline();
                extraIds.forEach(id => kPipe.hget(KEY_KILL_DATA, id));
                const kRes = await kPipe.exec();
                const kMap = {};
                kRes.forEach(([e, j]) => { if(!e && j) { const k = JSON.parse(j); kMap[k.killmail_id] = k; } });
                Object.values(allianceStatsDict).forEach(s => { if(s.maxKillId) s.maxKill = kMap[s.maxKillId]; if(s.maxLossId) s.maxLoss = kMap[s.maxLossId]; });
            }
            if (idsList.length === 1) allianceSummary = allianceStatsDict[idsList[0]];

            if (idsList.length === 2) {
                const [a, b] = idsList;
                const [avb, bva] = await redis.pipeline().zcount(`intel:interaction:${a}:${b}`, win, '+inf').zcount(`intel:interaction:${b}:${a}`, win, '+inf').exec();
                vsHeadToHead = { alliance_a: a, alliance_b: b, a_killed_b: avb[1]||0, b_killed_a: bva[1]||0 };
            }
            if (idsList.length >= 3) {
                interactionMatrix = {};
                const mPipe = redis.pipeline();
                const pairs = [];
                for(let i=0; i<idsList.length; i++) for(let j=0; j<idsList.length; j++) if(i!==j) { pairs.push({k:idsList[i],v:idsList[j]}); mPipe.zcount(`intel:interaction:${idsList[i]}:${idsList[j]}`, win, '+inf'); }
                const mRes = await mPipe.exec();
                pairs.forEach((p, i) => { if(!interactionMatrix[p.k]) interactionMatrix[p.k] = {}; interactionMatrix[p.k][p.v] = mRes[i][1]||0; });
            }
        }
    } catch (e) { 
        return [{ json: { error: e.message } }]; 
    } finally { 
        if (redis) redis.quit(); 
    }

    return [{ json: { 
        kills: finalKills, 
        total_count, 
        stats_24h, 
        trends, 
        isk_distribution, 
        activity_heatmap, 
        alliance_stats: allianceStatsDict, 
        alliance_summary: allianceSummary, 
        oldest_kill_id: oldest_kill_id_for_client, 
        latest_db_killmail_time, 
        vs_head_to_head: vsHeadToHead, 
        interaction_matrix: interactionMatrix 
    } }];
})();

const Redis = require('ioredis');

// --- Config ---
const REDIS_CONFIG = { host: 'redis', port: 6379, db: 0, connectTimeout: 5000, maxRetriesPerRequest: 2 };

// Keys
const KEY_KILLS_ALL = 'intel:kills:all';
const KEY_KILL_DATA = 'intel:kill:data';
const KEY_STATS_24H = 'intel:kills:24h_stats';
const KEY_CACHED_STATS = 'intel:cached:stats';
const KEY_CACHED_TRENDS = 'intel:cached:trends';

const redis = new Redis(REDIS_CONFIG);

try {
    const now = Math.floor(Date.now() / 1000);
    const thirtyDaysAgo = now - (86400 * 30);
    const twentyFourHoursAgo = now - 86400;
    const fortyEightHoursAgo = now - (86400 * 2);
    const sixtyDaysAgo = now - (86400 * 60);

    // 1. Fetch all required data in parallel
    const pipe = redis.pipeline();

    // Global Counts
    pipe.zcount(KEY_KILLS_ALL, thirtyDaysAgo, now);
    pipe.zcount(KEY_KILLS_ALL, sixtyDaysAgo, now);
    pipe.zrevrange(KEY_KILLS_ALL, 0, 0, 'WITHSCORES'); // Newest Kill ID

    // 24h & 48h Data (With Scores for bucketing)
    pipe.zrangebyscore(KEY_STATS_24H, twentyFourHoursAgo, now, 'WITHSCORES');
    pipe.zrangebyscore(KEY_STATS_24H, fortyEightHoursAgo, twentyFourHoursAgo, 'WITHSCORES');

    // 30-Day Hourly Distribution (For Historical Average)
    for(let h=0; h<24; h++) {
        pipe.zcount(`intel:kills:hour:${h}`, thirtyDaysAgo, now);
    }

    // Daily Stats (Last 30 Days)
    for (let i = 29; i >= 0; i--) {
        const start = now - ((i + 1) * 86400);
        const end = now - (i * 86400);
        pipe.zcount(KEY_KILLS_ALL, start, end);
    }

    // --- NEW: Fetch recent kills for alliance lastSeen calculation ---
    // Fetch up to the last 1000 kill IDs within the STATS_WINDOW_DAYS (30 days)
    pipe.zrevrangebyscore(KEY_KILLS_ALL, now, thirtyDaysAgo, 'WITHSCORES', 'LIMIT', 0, 1000);

    const results = await pipe.exec();

    // 2. Parse Results
    const total_count = results[0][1] || 0;
    const total_count_60d = results[1][1] || 0;
    const newestKillId = results[2][1]?.[0];

    const kills24hRaw = results[3][1] || [];
    const killsPrev24hRaw = results[4][1] || [];

    // --- NEW: Extract recent kill IDs and scores ---
    const recentKillsRaw = results[results.length - 1][1] || []; // Last result from the pipeline
    const recentKillIds = [];
    const recentKillTimestamps = {}; // Map kill ID to timestamp
    for (let i = 0; i < recentKillsRaw.length; i += 2) {
        recentKillIds.push(recentKillsRaw[i]);
        recentKillTimestamps[recentKillsRaw[i]] = parseInt(recentKillsRaw[i+1]);
    }


    // 3. Calculate 24h Stats (ISK & Kills) & Top Systems
    const kills_24h = kills24hRaw.length / 2;

    let total_isk_24h = 0;
    let top_systems = [];

    if (kills_24h > 0) {
        const iskPipe = redis.pipeline();
        for (let i = 0; i < kills24hRaw.length; i += 2) {
            iskPipe.hget(KEY_KILL_DATA, kills24hRaw[i]);
        }
        const iskRes = await iskPipe.exec();

        const systemCounts = {};
        total_isk_24h = iskRes.reduce((sum, [err, json]) => {
            if (!err && json) {
                const k = JSON.parse(json);
                // Aggregate System Counts
                const sys = k.solar_system_name || 'Unknown';
                systemCounts[sys] = (systemCounts[sys] || 0) + 1;
                return sum + (Number(k.total_value) || 0);
            }
            return sum;
        }, 0);

        top_systems = Object.entries(systemCounts)
            .sort((a, b) => b[1] - a[1])
            .slice(0, 10)
            .map(([name, count]) => ({ name, count }));
    }

    // 4. Calculate Previous 24h Stats (for Trends)
    const kills_prev_24h = killsPrev24hRaw.length / 2;
    let prev_isk = 0;
    if (kills_prev_24h > 0) {
         const iskPipe = redis.pipeline();
        for (let i = 0; i < killsPrev24hRaw.length; i += 2) {
            iskPipe.hget(KEY_KILL_DATA, killsPrev24hRaw[i]);
        }
        const iskRes = await iskPipe.exec();
        prev_isk = iskRes.reduce((sum, [err, json]) => {
            if (!err && json) {
                const k = JSON.parse(json);
                return sum + (Number(k.total_value) || 0);
            }
            return sum;
        }, 0);
    }

    // 5. Build Heatmap Data (Today vs Yesterday vs Avg)
    const activity_heatmap = {};

    const bucket = (rawList) => {
        const b = new Array(24).fill(0);
        for (let i = 0; i < rawList.length; i += 2) {
            const ts = parseFloat(rawList[i+1]);
            const h = new Date(ts * 1000).getUTCHours();
            b[h]++;
        }
        return b;
    };

    const todayBuckets = bucket(kills24hRaw);
    const yesterdayBuckets = bucket(killsPrev24hRaw);

    // results[5] is hour 0, results[28] is hour 23
    for (let h = 0; h < 24; h++) {
        const total30d = results[5 + h][1] || 0;
        const avg = Math.round(total30d / 30); // Daily average

        activity_heatmap[h] = {
            avg: avg,
            today: todayBuckets[h],
            yesterday: yesterdayBuckets[h]
        };
    }

    // 6. Build Daily Stats (Last 30 Days)
    const daily_stats = [];
    // results[29] is day -30, results[58] is day -1 (yesterday)
    // The loop for daily stats started at index 29 (5 + 24)
    const dailyStartIndex = 29;
    for (let i = 0; i < 30; i++) {
        const count = results[dailyStartIndex + i][1] || 0;
        // Calculate date label (e.g., "Jan 1")
        const d = new Date(now * 1000 - ((29 - i) * 86400 * 1000));
        const label = `${d.getUTCDate()}/${d.getUTCMonth() + 1}`;
        daily_stats.push({ label, count });
    }

    // 7. Calculate Trends
    function getTrend(current, previous) {
        if (previous === 0) return 'stable';
        const change = ((current - previous) / previous) * 100;
        if (change >= 50) return 'heating';
        if (change >= 10) return 'rising';
        if (change <= -50) return 'cooling';
        if (change <= -10) return 'falling';
        return 'stable';
    }

    const stats_24h = {
        kills: kills_24h,
        isk: total_isk_24h
    };

    const trends = {
        kills: getTrend(stats_24h.kills, kills_prev_24h),
        isk: getTrend(stats_24h.isk, prev_isk),
        avgValue: getTrend(
            stats_24h.kills > 0 ? stats_24h.isk / stats_24h.kills : 0,
            kills_prev_24h > 0 ? prev_isk / kills_prev_24h : 0
        ),
        total30d: getTrend(total_count, total_count_60d - total_count)
    };

    // 8. Cache Results
    const statsPayload = {
        stats_24h: stats_24h,
        total_count: total_count,
        latest_db_killmail_time: newestKillId ? new Date(parseInt(results[2][1][1]) * 1000).toISOString() : null,
        activity_heatmap: activity_heatmap,
        daily_stats: daily_stats,
        top_systems: top_systems
    };

    await redis.pipeline()
        .set(KEY_CACHED_STATS, JSON.stringify(statsPayload), 'EX', 3600)
        .set(KEY_CACHED_TRENDS, JSON.stringify(trends), 'EX', 3600)
        .exec();

    console.log(`[STATS-GEN] Updated stats: ${stats_24h.kills} kills, ${(total_isk_24h / 1e9).toFixed(2)}B ISK`);

    // --- NEW: Calculate and Cache Alliance Last Seen ---
    if (recentKillIds.length > 0) {
        const killDataPipe = redis.pipeline();
        recentKillIds.forEach(id => killDataPipe.hget(KEY_KILL_DATA, id));
        const killDataResults = await killDataPipe.exec();

        const allianceLastSeenMap = {}; // { allianceId: latestTimestamp }
        const corpLastSeenMap = {}; // { corpId: latestTimestamp }

        killDataResults.forEach(([err, json]) => {
            if (!err && json) {
                const kill = JSON.parse(json);
                const killTime = new Date(kill.killmail_time).getTime() / 1000; // Convert to Unix timestamp

                // Check victim alliance
                if (kill.victim?.alliance_id) {
                    const allianceId = String(kill.victim.alliance_id);
                    if (!allianceLastSeenMap[allianceId] || killTime > allianceLastSeenMap[allianceId]) {
                        allianceLastSeenMap[allianceId] = killTime;
                    }
                }

                if (kill.victim?.corporation_id) {
                    const corpId = String(kill.victim.corporation_id);
                    if (!corpLastSeenMap[corpId] || killTime > corpLastSeenMap[corpId]) {
                        corpLastSeenMap[corpId] = killTime;
                    }
                }

                // Check attacker alliances
                if (kill.attackers) {
                    kill.attackers.forEach(attacker => {
                        if (attacker.alliance_id) {
                            const allianceId = String(attacker.alliance_id);
                            if (!allianceLastSeenMap[allianceId] || killTime > allianceLastSeenMap[allianceId]) {
                                allianceLastSeenMap[allianceId] = killTime;
                            }
                        }
                        if (attacker.corporation_id) {
                            const corpId = String(attacker.corporation_id);
                            if (!corpLastSeenMap[corpId] || killTime > corpLastSeenMap[corpId]) {
                                corpLastSeenMap[corpId] = killTime;
                            }
                        }
                    });
                }
            }
        });

        // Update Redis for each alliance
        const allianceUpdatePipe = redis.pipeline();
        for (const allianceId in allianceLastSeenMap) {
            allianceUpdatePipe.hset(`alliance:summary:${allianceId}`, 'lastSeen', allianceLastSeenMap[allianceId]);
        }
        for (const corpId in corpLastSeenMap) {
            allianceUpdatePipe.hset(`corporation:summary:${corpId}`, 'lastSeen', corpLastSeenMap[corpId]);
        }
        await allianceUpdatePipe.exec();
        console.log(`[STATS-GEN] Updated lastSeen for ${Object.keys(allianceLastSeenMap).length} alliances and ${Object.keys(corpLastSeenMap).length} corporations.`);
    }

    return [{ json: { success: true, stats: statsPayload, trends, timestamp: new Date().toISOString() } }];

} catch (e) {
    console.error('[STATS-GEN] Error:', e.message);
    return [{ json: { error: e.message } }];
} finally {
    if (redis) redis.quit();
}
